def check_condition(h, a1, max_k=100):
    for k in range(1, max_k + 1):
        found = False
        a = a1
        seen = set()
        for _ in range(max_k * 2):
            if a % k == 0 and a != 0:
                found = True
                break
            a = h(a)
            if a in seen:
                break
            seen.add(a)
        if not found:
            return False
    return True

